/**
 * NAMI CMS — Careers
 *
 * Requires the "NAMI CMS — Core engine" snippet, version 1.2.0 or later
 * (collections). Adds a "Careers" menu:
 *   - All Vacancies / Add New: each job opening on the Careers page. A vacancy
 *     disappears from the website the day after its closing date.
 *   - Page: …: the rest of the Careers page (heading, how to apply, benefits,
 *     staff voices, first-job stories, placement).
 *
 * Field keys must match src/lib/cms/pages/careers/types.ts in the Next.js project.
 * The JSON block at the bottom is generated by `npm run cms:defaults`.
 */

if ( ! defined( 'ABSPATH' ) ) {
	return;
}

add_filter(
	'nami_cms_collections',
	function ( $collections ) {
		$collections['vacancies'] = array(
			'post_type'   => 'nami_vacancy',
			'singular'    => 'Vacancy',
