			'columns'     => array( 'department', 'employmentType', 'closesAt' ),
			// The vacancies bundled with the site are invented examples, so the
			// website shows only this list as soon as it is connected.
			'ready'       => true,
			'fields'      => array(
				'department'     => array( 'type' => 'text', 'label' => 'Wing / department', 'placeholder' => 'Naaya Aayam Multi-Disciplinary Institute', 'help' => 'Visitors can filter vacancies by this.' ),
